serialized_dashboard:
{
  "datasets": [
    {
      "name": "workforce",
      "displayName": "Workforce by category",
      "queryLines": [
        "SELECT EmployeeTypeName AS category, COUNT(DISTINCT StaffNumber) AS workers\n",
        "FROM ramsay_workforce.allocate.vwah_hoursassignment GROUP BY EmployeeTypeName ORDER BY workers DESC"
      ]
    },
    {
      "name": "unfilled7d",
      "displayName": "Unfilled shifts (7d)",
      "queryLines": [
        "SELECT COUNT(1) AS unfilled_shifts\n",
        "FROM ramsay_workforce.allocate.vw_open_gaps WHERE ShiftDate BETWEEN current_date() AND current_date()+7"
      ]
    },
    {
      "name": "absence",
      "displayName": "Absence by reason",
      "queryLines": [
        "SELECT UnavailabilityReasonGroup AS reason, COUNT(1) AS events, ROUND(SUM(LostHours),0) AS hours_lost, ROUND(SUM(SicknessHours),0) AS sickness_hours \n",
        "FROM ramsay_workforce.allocate.vwah_unavailability GROUP BY UnavailabilityReasonGroup"
      ]
    },
    {
      "name": "gaps",
      "displayName": "Open gaps",
      "queryLines": [
        "SELECT SiteName, Grade, ShiftDate, ShiftName, GapReason \n",
        "FROM ramsay_workforce.allocate.vw_open_gaps WHERE ShiftDate BETWEEN current_date() AND current_date()+7 ORDER BY ShiftDate"
      ]
    }
  ],
  "pages": [
    {
      "name": "overview",
      "displayName": "Executive Overview",
      "layout": [
        {
          "widget": {
            "name": "title",
            "multilineTextboxSpec": {
              "lines": [
                "# Ramsay Workforce & Absence — Executive View"
              ]
            }
          },
          "position": {
            "x": 0,
            "y": 0,
            "width": 6,
            "height": 1
          }
        },
        {
          "widget": {
            "name": "sub",
            "multilineTextboxSpec": {
