                "Workforce headcount, sickness/absence and unfilled shifts across 8 hospitals. _Synthetic Allocate/HealthRoster data._"
              ]
            }
          },
          "position": {
            "x": 0,
            "y": 1,
            "width": 6,
            "height": 2
          }
        },
        {
          "widget": {
            "name": "h1",
            "multilineTextboxSpec": {
              "lines": [
                "## Workforce & open shifts"
              ]
            }
