          "position": {
            "x": 0,
            "y": 3,
            "width": 6,
            "height": 1
          }
        },
        {
          "widget": {
            "name": "bar-workforce",
            "queries": [
              {
                "name": "main_query",
                "query": {
                  "datasetName": "workforce",
                  "fields": [
                    {
                      "name": "category",
                      "expression": "`category`"
                    },
                    {
                      "name": "sum(workers)",
                      "expression": "SUM(`workers`)"
                    }
                  ],
                  "disaggregated": false
                }
              }
            ],
            "spec": {
              "version": 3,
              "widgetType": "bar",
              "encodings": {
                "x": {
                  "fieldName": "category",
